 Widget _mini(String a,String b,IconData i)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.white.withValues(alpha:.09),borderRadius:BorderRadius.circular(16)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i,color:Colors.white70,size:18),Text(a,style:const TextStyle(color:Colors.white70,fontSize:12)),Text(b,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w800),overflow:TextOverflow.ellipsis)]));
